local E = require 'ejoysdk_lua.ejoysdk'
local EV = require "ejoysdk_lua.ejoysdk_vendors"
local AGST_TOKEN = require 'ejoysdk_lua.user_center.agst_token_manager'
local DEVICE_ID = require 'ejoysdk_lua.device_id.ejoysdk_device_id'
local USER = require 'ejoysdk_lua.user_center.ejoysdk_usercenter'
local AGST = require 'ejoysdk_lua.vendors.agst_account'
local ESTAT = require 'ejoysdk_lua.ejoysdk_stat'
local CONSTANTS = require 'ejoysdk_lua.ejoysdk_constants'
local OFFICIAL = require 'ejoysdk_lua.vendors.official'
local EM = require "ejoysdk_lua.ejoysdk_module"
local QL = require "ejoysdk_lua.ejoysdk_qualitylog"
--local ET = require "ejoysdk_lua.ejoysdk_topic"
local unpack = table.unpack or unpack

local M = {}

local TAG = EM.MODULE.EJOYSDK_BASE_MODULE .. "channel_manager"

-- 授权时附带信息
local AUTH_ATTACH_INFO = "auth_attach_info"
local ATTACH_INFO_KEY = {
    AUTH_BIZ_TYPE = "auth_biz_type", -- 授权用于使用的业务类型
    AUTH_RESULT_LISTENER = "auth_result_listener" -- 授权结果回调
}

local AUTH_BIZ_TYPE = {
    BIND = "bind", --绑定业务
    LOGIN = "login" --登录业务
}

local function use_user_center(vendor)
    if vendor and vendor.use_user_center and vendor.use_user_center() then
        return true
    else
        return false
    end
end

local function wrap_listeners(listeners)
    local origin_auth_listener = listeners.auth_listener
    listeners.auth_listener = function(vendor_name, succ, ...)
        local vendor = EV.get(vendor_name)
        if use_user_center(vendor) then
            E.LOG.debug(TAG, "auth_listener callback, check current vendor is using user_center, and begin check auth_result_listener")
            local vendor_attach_info = vendor[AUTH_ATTACH_INFO]
            local auth_result_listener = nil
            if vendor_attach_info ~= nil then
                auth_result_listener = vendor_attach_info[ATTACH_INFO_KEY.AUTH_RESULT_LISTENER]
            end

            if auth_result_listener then
                E.LOG.debug(TAG, "auth for biz succ, now return to request bind")
                auth_result_listener(succ, vendor_name, origin_auth_listener, ...)
            else
                local auth_biz_type = ''
                if vendor_attach_info ~= nil then
                    auth_biz_type = vendor_attach_info[ATTACH_INFO_KEY.AUTH_BIZ_TYPE]
                end

                local err_msg = 'no result listener, vendor_name:'..vendor_name..', auth_biz_type:'..(auth_biz_type or 'nil')
                E.LOG.warn(TAG, err_msg)
                origin_auth_listener(vendor_name, false, { code = CONSTANTS.OFFICIAL_ERR_CODES.CODE_PARAM_INVALID, msg = err_msg})
            end
        else
            E.LOG.debug(TAG, "auth_listener callback, check current vendor is NOT using user_center, return to gangplank")
            origin_auth_listener(vendor_name, succ, ...)
        end
    end

    local origin_logout_listener = listeners.logout_listener
    listeners.logout_listener = function(vendor_name, ext)
        local vendor = EV.get(vendor_name)
        if use_user_center(vendor) then
            E.LOG.debug(TAG, "need call user_center logout")
            USER.logout()
        end

        origin_logout_listener(vendor_name, ext)
    end

    return listeners
end

local function is_vendor_unspecified(vendor_name)
    return vendor_name == nil or vendor_name == '' or vendor_name == 'auto'
end

function M.get_vendor(vendor_name, ability)
    local ret_vendor_name = vendor_name

    -- 未指定vendorname
    if is_vendor_unspecified(vendor_name) then
        E.LOG.debug(TAG, "需要自动检查vendor")
        assert(ability, "vendor_name and ability all unknown")

        local vendor_name_list = EV.get_native_vendors(ability)
        E.log(vendor_name_list)
        for _, sdk in pairs(vendor_name_list) do
            -- 如果vendor_name不传，则优先用聚合vendor
            if EV.UMBRELLA_VENDORS[sdk] then
                ret_vendor_name = sdk
                break
            end
        end

        -- is support for ret_vendor_name
        local _vendor = EV.get(ret_vendor_name)
        if is_vendor_unspecified(ret_vendor_name) or not _vendor or not _vendor:is_support_ability({ability}) then
            E.LOG.warn(TAG, "umbrella vendor not find or not support:" .. tostring(ret_vendor_name) .. ", now check single vendor support")
            -- find the support one with is_support_ability. use in oversea scene
            for i=1, #vendor_name_list do
                local vn = vendor_name_list[i]
                _vendor = EV.get(vn)
                if _vendor and _vendor:is_support_ability({ability}) then
                    E.LOG.debug(TAG, "find support vendor:" .. tostring(vn))
                    ret_vendor_name = vn
                    break
                end
            end
        end
    end

    local vendor_result = {}
    vendor_result.vendor_name = ret_vendor_name
    vendor_result.vendor = EV.get(ret_vendor_name)

    E.LOG.debug(TAG, "get_vendor ret, origin vendor_name:"..(vendor_name or 'nil')..', ret_vendor_name:'..(ret_vendor_name or 'nil'))
    return vendor_result
end

-- 检查vendor是否支持指定的abilities
-- @param vendor_name: vendor名，详细见 {@link ejoysdk_vendors#VENDORS_NAME}
-- @param abilities, 字符串数组，存放支持的能力，详细见 {@link ejoysdk_vendors#ABILITY}
function M.is_support_ability(vendor_name, abilities)
    if not vendor_name or vendor_name == '' then
        E.LOG.warn(TAG, "vendor name is invalid")
        return false
    end

    local _vendor = EV.get(vendor_name)
    local support_result = _vendor:is_support_ability(abilities)
    E.LOG.debug(TAG, "is_support_ability, vendor_name:" .. tostring(vendor_name) .. ", support:" .. tostring(support_result))
    return support_result
end

local function need_use_user_center(vendors)
    for vendor_name, _value in pairs(vendors) do
        local vendor = EV.get(vendor_name)
        if use_user_center(vendor) then
            E.LOG.debug(TAG, "need_use_user_center find vendor need user_center, now return true :"..vendor_name)
            return true
        end
    end

    E.LOG.debug(TAG, "need_use_user_center NOT find vendor need user_center, now return false :")
    return false
end

-- 初始化 vendors
function M.init(vendors, listeners, cb)
    -- 设备ID初始化
    DEVICE_ID.init()

    if need_use_user_center(vendors) then
        -- 初始化usercenter
        -- 游客ID组件初始化
        AGST_TOKEN.init()
        USER.init(function(succ, ...)
            if succ then
                E.LOG.debug(TAG, "start init all vendors")
                -- 初始化所有vendor
                EV.init(vendors, wrap_listeners(listeners), cb)

                -- stat usercenter init succ
                QL.commit_action_succ_main("ejoy_usercenter_init_end")
            else
                E.LOG.debug(TAG, "user center init failed")
                cb(false, ...)

                -- stat usercenter init failed
                local _code, _msg = ...
                QL.commit_action_fail_main("ejoy_usercenter_init_end", nil, _code, _msg)
            end
        end)
    else
        E.LOG.debug(TAG, "start init all vendors")
        -- 初始化所有vendor
        EV.init(vendors, wrap_listeners(listeners), cb)
    end
end

local function set_vendor_attach_info(vendor, params)
    vendor[AUTH_ATTACH_INFO] = params
end

-- 去用户中心绑定
local function bind_user_center(vendor_name, third_party_token, cb)
    AGST_TOKEN.get_token(function(agst_token)
        USER.bind(agst_token, vendor_name, third_party_token, function(succ, ...)
            if succ then
                local EG = require 'ejoysdk_lua.ejoysdk_gangplank'
                local last_login_vendor = EG.get_last_login()
                EG.set_last_login(vendor_name)
                --check_agst_bind_account(last_login_vendor,vendor_name)
                if last_login_vendor == AGST.VENDOR_NAME and vendor_name ~= AGST.VENDOR_NAME then
                    E.LOG.warn(TAG, 'bind_user_center succ, and need logout for agst change to regular account')
                    -- 如果是跟游客绑定，则此时定义为转正，需要标记
                    OFFICIAL.mark_agst_official()
                    --EG.logout()

                    -- 转正不再登出, 但需要更新登录信息
                    local userinfo = EG.user_info() or {}
                    userinfo.platform = vendor_name
                    userinfo.guest = false

                    local ET = require 'ejoysdk_lua.ejoysdk_topic'
                    ET.publish(ET.gangplank.USER_INFO_UPDATE,userinfo)
                end
            end

            cb(succ, ...)
        end)
    end)
end

-- 调用用户中心登录
local function login_user_center(vendor_name, third_party_token, is_create, challenge_info, ext, cb)
    E.LOG.debug(TAG, 'login_user_center begin')

    local function create_new_account(token)
        E.LOG.debug(TAG, 'user choose create_new_account')
        local ptoken = third_party_token
        if type(token) == 'string' and '' ~= token then
            -- pgs绑定的话需要更新三方token
            ptoken = token
        end
        login_user_center(vendor_name, ptoken, true, challenge_info, ext, cb)
    end

    local function bind_agst(token)
        E.LOG.debug(TAG, 'user choose bind_agst')
        -- now bind response has same result as login, so we directly callback
        local ptoken = third_party_token
        if type(token) == 'string' and '' ~= token then
            -- pgs绑定的话需要更新三方token
           ptoken = token
        end
        bind_user_center(vendor_name, ptoken, function(succ,...)
            if(succ)then
                -- 此处肯定是游客绑定，则此时定义为转正，需要标记
                OFFICIAL.mark_agst_official()


                --E.WebView.close() --登录过程中的游客转正
            end
            cb(succ,...)
        end)
    end

    --  call user center
    AGST_TOKEN.get_token(function(agst_token)
        USER.login(vendor_name, third_party_token, agst_token, is_create, challenge_info, ext, function(succ, ...)
            if not succ then
                local err_code = ...
                if err_code == USER.USER_CENTER_ERROR_CODES.ERR_AGST_ROLE_BIND_CONFLICT then
                    local code,msg,ext_info = ...
                    cb(false, code,msg,ext_info,create_new_account,bind_agst)
                    return
                end
            end

            -- 原样返回
            cb(succ, ...)
        end)
    end)
end

-- 全局错误码处理器，目前主要用于处理海外账号中心token过期，后续SDK实现token自动刷新功能
local function global_errcode_handler(_vendor_name, err_code)
    E.LOG.debug(TAG, 'global_errcode_handler, errCode:' .. (err_code or 'nil'))
    if err_code == USER.USER_CENTER_ERROR_CODES.ERR_TOKEN_EXPIRED
            or err_code == USER.USER_CENTER_ERROR_CODES.ERR_TOKEN_INVALID then
        E.LOG.warn(TAG, 'global_errcode_handler err_code:' .. err_code .. ', token is invalid or expired, now need logout')

        local EG = require 'ejoysdk_lua.ejoysdk_gangplank'
        EG.logout()
        return true
    end

    return false
end

local function handle_usercenter_bind_failed(vendor_name, bind_listener, ...)
    E.LOG.warn(TAG, 'handle_usercenter_bind_failed, vendor_name: ' .. tostring(vendor_name))
    local err_code, err_msg = ...

    if global_errcode_handler(vendor_name, err_code) then
        return
    end

    local fail_callback = function(code, msg)
        bind_listener(false, code, msg)
    end

    local vendor = EV.get(vendor_name)
    if vendor and vendor.login_fail and vendor.login_fail(err_code, nil, fail_callback) then
        E.LOG.debug(TAG,'handle bind fail for err_code: ' .. tostring(err_code))
        return
    end

    fail_callback(err_code, err_msg)
end

local function handle_usercenter_login_failed(vendor_name, auth_listener, outsource, ...)
    E.LOG.warn(TAG, 'handle_usercenter_login_failed, vendor_name: ' .. tostring(vendor_name))
    local err_code, err_msg, ext_info, create_new_account_fun, bind_agst_fun = ...

    local vendor = EV.get(vendor_name)

    local login_fail_callback = function(_code, _msg)
        ext_info = ext_info or {}
        ext_info.ptoken = (outsource or {}).ptoken
        auth_listener(vendor_name,false,{ code = _code, msg = _msg, ext_info = ext_info, create_new_account = create_new_account_fun, bind_agst = bind_agst_fun })
    end

    if vendor and vendor.login_fail and vendor.login_fail(err_code, nil, login_fail_callback) then
        E.LOG.debug(TAG, 'handle login fail for err_code: ' .. tostring(err_code))
        return
    end
    login_fail_callback(err_code, err_msg)
end

local function inject_usercenter_bind_if_need(vendor, cb)
    if not use_user_center(vendor) then
        E.LOG.debug(TAG, "inject_usercenter_bind_if_need NO need use user center")
        return
    end

    E.LOG.debug(TAG, "inject_usercenter_bind_if_need start inject user center")
    local auth_callback_handler = function(succ, vendor_name, _auth_listener, ...)
        if succ then
            local outsource, _ext = ...
            E.LOG.debug(TAG, 'bind auth with vendor_name succ:' .. vendor_name .. ', now start call bind_user_center')
            bind_user_center(vendor_name, outsource.ptoken, function(succ2, ...)
                if succ2 then
                    E.LOG.debug(TAG, 'bind success, vendor_name:' .. vendor_name)
                    cb(true, ...)

                    -- 统计打点
                    ESTAT.stat_action('bind_result', vendor_name, succ2)
                else
                    local code, msg = ...
                    E.LOG.warn(TAG, 'bind failed, vendor_name:' .. vendor_name .. ', code:' .. code .. ', msg:' .. (msg or 'nil'))
                    handle_usercenter_bind_failed(vendor_name, cb, ...)

                    -- 统计打点
                    ESTAT.stat_action_fail('bind_result', vendor_name, ...)
                end
            end)
        else
            local login_fail_info = ...
            local err_code = login_fail_info.code or -1
            local err_msg = login_fail_info.msg or ''
            E.LOG.warn(TAG, 'bind failed, code:' .. err_code .. ', err_msg:' .. err_msg)
            cb(false, err_code, err_msg)

            -- 统计打点
            ESTAT.stat_action_fail('bind_result', vendor_name, ...)
        end
    end

    local bind_attach_info = {
        [ATTACH_INFO_KEY.AUTH_BIZ_TYPE] = AUTH_BIZ_TYPE.BIND,
        [ATTACH_INFO_KEY.AUTH_RESULT_LISTENER] = auth_callback_handler
    }

    set_vendor_attach_info(vendor, bind_attach_info)
end

function M.bind(vendor_name, cb)
    local vendor = EV.get(vendor_name)

    inject_usercenter_bind_if_need(vendor, cb)

    if not vendor or not vendor.bind then
        E.LOG.debug(TAG, "bind vendor_name not has bind method, return:" .. vendor_name)
        return
    end

    E.LOG.debug(TAG, "bind begin bind_logout")
    vendor.bind_logout(function(_ext_params)
        E.LOG.debug(TAG, 'bind logout succ!')
        vendor.login()
    end)
end

function M.get_bind_info(cb)
    local EG = require 'ejoysdk_lua.ejoysdk_gangplank'
    local last_login_vendor = EG.get_last_login()
    USER.get_bind_info(function(succ, ...)
        if not succ then
            local code, _msg = ...
            --处理通用错误码
            global_errcode_handler(last_login_vendor, code)
        end

        cb(succ, ...)
    end)
end

local challenge_login_params

local function do_login_user_center(...)
    --  call user center
    local login_params = {...}
    local vendor_name, outsource, ext, is_create, challenge_info, login_ext, auth_listener = ...
    login_user_center(vendor_name, outsource.ptoken, is_create, challenge_info, login_ext, function(succ2, ...)
        if succ2 then
            QL.commit_action_main('login_result', vendor_name, succ2,outsource)
            local user_info = ...
            outsource.ptoken = user_info.token or ''
            outsource.isPga = user_info.isPga or false -- PGS绑定判断
            outsource.openId = user_info.openId or '' -- uid

            E.LOG.debug(TAG, "login_user_center succ!")
            auth_listener(vendor_name, true, outsource, ext)
        else
            local err_code, err_msg = ...
            QL.commit_action_fail_main('login_result', vendor_name, err_code, err_msg)

            if err_code == USER.USER_CENTER_ERROR_CODES.ERR_NEED_CHALLENGE then
                -- 暂存宙斯盾挑战时的登录信息，玩家完成挑战后继续登录
                challenge_login_params = login_params
            end

            E.LOG.warn(TAG, "handle_usercenter_login_failed err_code:"..err_code..", err_msg:"..(err_msg or 'nil'))
            handle_usercenter_login_failed(vendor_name, auth_listener, outsource, ...)
        end
    end)
end

function M.login_with_challenge_info(challenge_info)
    if challenge_info == nil or challenge_login_params == nil then
        return
    end

    E.LOG.debug(TAG, 'challenge_login_params')
    E.LOG.debug(TAG, challenge_login_params)
    -- 这里还是显式地展开，避免以后改了 do_login_user_center 参数的顺序，没有检查这里的调用
    local vendor_name, outsource, ext, is_create, _, login_ext, auth_listener = unpack(challenge_login_params)
    challenge_login_params = nil
    do_login_user_center(vendor_name, outsource, ext, is_create, challenge_info, login_ext, auth_listener)
end

local function inject_usercenter_login_if_need(vendor,login_ext)
    if not use_user_center(vendor) then
        E.LOG.debug(TAG, "inject_usercenter_login_if_need NO need use user center")
        return
    end

    E.LOG.debug(TAG, "inject_usercenter_login_if_need start inject user center")
    local auth_callback_handler = function(succ, vendor_name, auth_listener, ...)
        if succ then
            local outsource, ext = ...
            E.LOG.debug(TAG, 'proxy_auth_listener login succ, vendor_name:' .. (vendor_name or 'nil') .. ', token:' .. (outsource.ptoken or 'nil'))
            do_login_user_center(vendor_name, outsource, ext, false, nil, login_ext, auth_listener)
        else
            ESTAT.stat_action_fail('login_result', vendor_name, ...)
            auth_listener(vendor_name, false, ...)
        end
    end

    local login_attach_info = {
        [ATTACH_INFO_KEY.AUTH_BIZ_TYPE] = AUTH_BIZ_TYPE.LOGIN,
        [ATTACH_INFO_KEY.AUTH_RESULT_LISTENER] = auth_callback_handler
    }

    set_vendor_attach_info(vendor, login_attach_info)
end

-- 登录逻辑，包含登录账号中心
-- vendor_name: 不能为空
-- proxy_vendor: 可选，可以为空
function M.login(vendor_name,ext)
    local vendor = EV.get(vendor_name)
    inject_usercenter_login_if_need(vendor, ext)

    -- publish vendor login start
    vendor.login(ext)
end

function M.open_user_center(vendor_name)
   local vendor=EV.get(vendor_name)

    if vendor and vendor.open_user_center then
        vendor.open_user_center()
    end
end

-- 资料完善
function M.open_userinfo_completion(vendor_name,cb)
    local vendor=EV.get(vendor_name)

    if vendor and vendor.open_userinfo_completion then
        vendor.open_userinfo_completion(cb)
    end
end

return M
